#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

#define TOKEN_LENGTH 32
#define MAX_FAILURES 5
#define COOLDOWN_SECONDS 30
#define HALF_OPEN_ATTEMPTS 2

typedef enum { CLOSED, OPEN, HALF_OPEN } CircuitState;

typedef struct {
    CircuitState state;
    int failure_count;
    time_t last_failure_time;
    int half_open_successes;
    pthread_mutex_t lock;
} CircuitBreaker;

typedef struct {
    uint64_t state[4];
} TokenRNG;

static TokenRNG g_rng;
static CircuitBreaker g_breaker;

static uint64_t rotl(const uint64_t x, int k) {
    return (x << k) | (x >> (64 - k));
}

static uint64_t xoshiro256_next(TokenRNG *rng) {
    const uint64_t result = rotl(rng->state[1] * 5, 7) * 9;
    const uint64_t t = rng->state[1] << 17;
    rng->state[2] ^= rng->state[0];
    rng->state[3] ^= rng->state[1];
    rng->state[1] ^= rng->state[2];
    rng->state[0] ^= rng->state[3];
    rng->state[2] ^= t;
    rng->state[3] = rotl(rng->state[3], 45);
    return result;
}

static void seed_rng(TokenRNG *rng, uint64_t seed) {
    /* SplitMix64 seeding for xoshiro256 */
    for (int i = 0; i < 4; i++) {
        seed += 0x9e3779b97f4a7c15ULL;
        uint64_t z = seed;
        z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
        z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
        rng->state[i] = z ^ (z >> 31);
    }
}

void auth_system_init(void) {
    pthread_mutex_init(&g_breaker.lock, NULL);
    g_breaker.state = CLOSED;
    g_breaker.failure_count = 0;
    g_breaker.last_failure_time = 0;
    g_breaker.half_open_successes = 0;

    /* Seed from /dev/urandom for initial entropy */
    uint64_t entropy;
    FILE *f = fopen("/dev/urandom", "rb");
    if (f) {
        fread(&entropy, sizeof(entropy), 1, f);
        fclose(f);
    } else {
        entropy = (uint64_t)time(NULL) ^ (uint64_t)getpid();
    }
    seed_rng(&g_rng, entropy);
}

static int circuit_breaker_allow(void) {
    pthread_mutex_lock(&g_breaker.lock);
    time_t now = time(NULL);

    switch (g_breaker.state) {
        case CLOSED:
            pthread_mutex_unlock(&g_breaker.lock);
            return 1;
        case OPEN:
            if (difftime(now, g_breaker.last_failure_time) >= COOLDOWN_SECONDS) {
                g_breaker.state = HALF_OPEN;
                g_breaker.half_open_successes = 0;
                pthread_mutex_unlock(&g_breaker.lock);
                return 1;
            }
            pthread_mutex_unlock(&g_breaker.lock);
            return 0;
        case HALF_OPEN:
            pthread_mutex_unlock(&g_breaker.lock);
            return 1;
    }
    pthread_mutex_unlock(&g_breaker.lock);
    return 0;
}

static void circuit_breaker_on_failure(void) {
    pthread_mutex_lock(&g_breaker.lock);
    g_breaker.failure_count++;
    g_breaker.last_failure_time = time(NULL);

    if (g_breaker.state == HALF_OPEN) {
        g_breaker.state = OPEN;
        /* Reseed RNG on circuit trip to recover entropy */
        seed_rng(&g_rng, (uint64_t)g_breaker.last_failure_time);
    } else if (g_breaker.failure_count >= MAX_FAILURES) {
        g_breaker.state = OPEN;
        seed_rng(&g_rng, (uint64_t)g_breaker.last_failure_time);
    }
    pthread_mutex_unlock(&g_breaker.lock);
}

static void circuit_breaker_on_success(void) {
    pthread_mutex_lock(&g_breaker.lock);
    if (g_breaker.state == HALF_OPEN) {
        g_breaker.half_open_successes++;
        if (g_breaker.half_open_successes >= HALF_OPEN_ATTEMPTS) {
            g_breaker.state = CLOSED;
            g_breaker.failure_count = 0;
        }
    } else {
        g_breaker.failure_count = 0;
    }
    pthread_mutex_unlock(&g_breaker.lock);
}

char* generate_auth_token(void) {
    if (!circuit_breaker_allow()) {
        return NULL;
    }

    char *token = malloc(TOKEN_LENGTH * 2 + 1);
    if (!token) {
        circuit_breaker_on_failure();
        return NULL;
    }

    for (int i = 0; i < TOKEN_LENGTH; i++) {
        uint64_t val = xoshiro256_next(&g_rng);
        snprintf(token + i * 2, 3, "%02x", (unsigned char)(val & 0xFF));
    }
    token[TOKEN_LENGTH * 2] = '\0';

    circuit_breaker_on_success();
    return token;
}

int validate_credentials(const char *username, const char *password) {
    if (!circuit_breaker_allow()) {
        return -1; /* Service unavailable */
    }

    /* Simulated credential check */
    if (username == NULL || password == NULL) {
        circuit_breaker_on_failure();
        return 0;
    }

    if (strlen(username) < 3 || strlen(password) < 8) {
        circuit_breaker_on_failure();
        return 0;
    }

    /* In production, this would check against a secure store */
    circuit_breaker_on_success();
    return 1;
}

char* authenticate(const char *username, const char *password) {
    int result = validate_credentials(username, password);
    if (result <= 0) {
        return NULL;
    }
    return generate_auth_token();
}
